def classify_existing_components(apps, schema_editor):
    Product = apps.get_model("catalog", "Product")
    products = Product.objects.filter(category__slug="linh-kien-pc")

    for product in products.iterator():
        name = (product.name or "").casefold()
        specs = product.specifications if isinstance(product.specifications, dict) else {}
        normalized_specs = {
            str(key).casefold(): str(value).casefold()
            for key, value in specs.items()
        }
        all_spec_text = " ".join(normalized_specs.values())

        if "chipset" in normalized_specs or "mainboard" in name or "motherboard" in name:
            kind = "mainboard"
        elif (
            "gpu" in normalized_specs
            or "vram" in normalized_specs
            or any(marker in name for marker in ("card màn hình", "vga", "geforce", "radeon", "rtx", "rx "))
        ):
            kind = "vga"
        elif (
            "công suất" in normalized_specs
            or "psu" in name
            or "nguồn" in name
        ):
            kind = "psu"
        elif "socket" in normalized_specs and "chipset" not in normalized_specs:
            kind = "cpu"
        elif (
            "ram" in name
            or "ddr" in name
            or "ddr" in all_spec_text
        ):
            kind = "ram"
        elif (
            any(marker in name for marker in ("ssd", "nvme", "sata"))
            or "nvme" in all_spec_text
            or "sata" in all_spec_text
        ):
            kind = "ssd"
        else:
            # Leave ambiguous items unclassified so an administrator can choose
            # the correct group from the product form.
            continue

        Product.objects.filter(pk=product.pk).update(component_kind=kind)


